#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


cd "$(dirname "$0")/.."
ENV_FILE=.env.production
REMOTE_DIR=cardano-forecast-club
REPO_URL=https://github.com/Will413028/cardano-forecast-club.git
TOTAL_STAGES=8

banner "Forecast Club — public deployment (local chain mode)"

stage "Domain — register on Cloudflare"
say "Resend needs a domain whose DNS you control; Cloudflare Tunnel needs it on Cloudflare."
open_url "https://dash.cloudflare.com/?to=/:account/domains/register"
step "Search for a domain, buy it (Domain Registration → Register Domains)."
step "Wait until it shows as Active under Websites."
ask DOMAIN "Registered domain (e.g. example.com):"
ask APP_HOST "Public hostname for the app (e.g. forecast.$DOMAIN):"
write_env DOMAIN "$DOMAIN"
write_env APP_HOST "$APP_HOST"
write_env PUBLIC_ORIGIN "https://$APP_HOST"

stage "Resend — verify the sending domain"
open_url "https://resend.com/domains"
step "Sign up / sign in, then Add Domain → enter $DOMAIN."
step "Use the offered Cloudflare auto-configure, or copy each DNS record it lists"
step "  (MX + SPF TXT on the send subdomain, DKIM TXT) into Cloudflare DNS."
step "Click Verify and wait until the domain status is Verified."
pause "Press Enter once Resend shows Verified"
ask MAIL_LOCAL "Sender address local part [login]:"
write_env MAIL_FROM "Forecast Club <${MAIL_LOCAL:-login}@$DOMAIN>"

stage "Resend — SMTP credentials"
open_url "https://resend.com/api-keys"
step "Create API Key → permission: Sending access → domain: $DOMAIN."
step "Copy the key (starts re_). It is shown only once."
ask_secret RESEND_KEY "Paste the API key (hidden; Enter keeps a saved one):"
if [[ -n "$RESEND_KEY" ]]; then
  write_env SMTP_URL "smtps://resend:${RESEND_KEY}@smtp.resend.com:465"
elif [[ -n "$(_existing SMTP_URL || true)" ]]; then
  note "Keeping the saved SMTP_URL."
else
  warn "No API key entered; re-run this wizard to finish."; exit 1
fi

stage "Operator account"
say "These sign-in emails get Operator rights (publish questions, resolve, void)."
ask ADMIN_EMAILS "Operator email(s), comma-separated:"
write_env ADMIN_EMAILS "$ADMIN_EMAILS"
write_env CHAIN_MODE local
note "CHAIN_MODE stays local: receipts are labelled simulations until Preprod wallet setup."

stage "Cloudflare Tunnel — ingress without open ports"
open_url "https://one.dash.cloudflare.com/"
step "Networks → Tunnels (newer UI may say Connectors) → Create a tunnel → Cloudflared."
step "Name it forecast-club → Save."
step "On the install page, copy only the token after 'cloudflared service install'."
ask_secret TUNNEL_TOKEN "Paste the tunnel token (hidden):"
write_env TUNNEL_TOKEN "$TUNNEL_TOKEN"
step "Next → Public Hostname: subdomain/domain = $APP_HOST"
step "  Service type HTTP, URL app:3318 → Save tunnel."
pause "Press Enter once the public hostname is saved"

stage "Database password"
if [[ -n "$(_existing POSTGRES_PASSWORD || true)" ]]; then
  note "Keeping the existing POSTGRES_PASSWORD (the database volume already uses it)."
else
  write_env POSTGRES_PASSWORD "$(openssl rand -hex 24)"
fi
chmod 600 "$ENV_FILE"
note "$ENV_FILE is gitignored and now mode 600."
pause

stage "Deploy to the VM"
ask DEPLOY_SSH "SSH host alias of the VM:"
write_env DEPLOY_SSH "$DEPLOY_SSH"
ssh -o BatchMode=yes "$DEPLOY_SSH" 'docker compose version >/dev/null && docker info >/dev/null' \
  || { warn "SSH or Docker Compose is not ready on $DEPLOY_SSH; fix it and re-run."; exit 1; }
say "Will run on $DEPLOY_SSH: clone or fast-forward ~/$REMOTE_DIR (main), upload $ENV_FILE,"
say "then docker compose up -d --build (app, postgres, cloudflared)."
if confirm "Deploy now?"; then
  ssh "$DEPLOY_SSH" "if [ -d $REMOTE_DIR/.git ]; then git -C $REMOTE_DIR pull --ff-only; else git clone $REPO_URL $REMOTE_DIR; fi"
  scp -q "$ENV_FILE" "$DEPLOY_SSH:$REMOTE_DIR/.env.production"
  ssh "$DEPLOY_SSH" "chmod 600 $REMOTE_DIR/.env.production && cd $REMOTE_DIR && docker compose --env-file .env.production -f deploy/compose.prod.yaml up -d --build"
else
  SKIPPED+=("deploy to $DEPLOY_SSH (re-run this wizard)")
fi

stage "Verify the public site"
URL="https://$APP_HOST"
for _ in $(seq 1 30); do curl -fsS "$URL/api/config" >/dev/null 2>&1 && break; sleep 2; done
if curl -fsS "$URL/api/config" | grep -q '"localAuthPreview":false'; then
  printf '  %s✓%s %s answers in production mode\n' "$GREEN" "$RESET" "$URL"
else
  warn "$URL/api/config did not answer in production mode; check: ssh $DEPLOY_SSH 'cd $REMOTE_DIR && docker compose -f deploy/compose.prod.yaml logs'"
  SKIPPED+=("public site check")
fi
ssh "$DEPLOY_SSH" "cd $REMOTE_DIR && docker compose --env-file .env.production -f deploy/compose.prod.yaml exec -T app pnpm --silent ops-check" \
  || SKIPPED+=("ops-check reported problems")
open_url "$URL"
step "Sign in with an Operator email and confirm the login email arrives."
pause "Press Enter once you have signed in"

finish
